INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Abstimmung mit Stakeholdern nur für große Projekte wichtig?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Projekte brauchen Akzeptanz"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit der Abstimmung mit Stakeholdern?', 3, '[{"text": "Akzeptanz sicherstellen", "correct": true, "because": "Fördert Zusammenarbeit"}, {"text": "Datenmenge maximieren", "correct": false, "because": "Nicht primär"}, {"text": "Schnelle Verarbeitung", "correct": false, "because": "Kommunikation im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zur Abstimmung mit Stakeholdern?', 5, '[{"text": "Kommunikationsplan", "correct": true, "because": "Definiert Austausch"}, {"text": "Feedbackschleifen", "correct": true, "because": "Ermöglicht Anpassung"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Kommunikationsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Feedback von Stakeholdern verbessert Projekte. b) Abstimmung ist nur für Projektleiter nötig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Alle Beteiligten profitieren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Abstimmung mit Stakeholdern?', 4, '[{"text": "Stakeholder-Interessen", "correct": false, "because": "Kern der Abstimmung"}, {"text": "Feedback-Mechanismen", "correct": false, "because": "Fördert Anpassung"}, {"text": "Visuelles Design", "correct": true, "because": "Kein Kommunikationsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Abstimmung mit Stakeholdern die Projektakzeptanz erhöht?', 2, '[{"text": "Ja", "correct": true, "because": "Fördert Zustimmung"}, {"text": "Nein", "correct": false, "because": "Teil der Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Mittel ist typisch für die Abstimmung mit Stakeholdern?', 3, '[{"text": "Meetings", "correct": true, "because": "Ermöglicht direkten Austausch"}, {"text": "Hohe Serverleistung", "correct": false, "because": "Irrelevant"}, {"text": "Statische IPs", "correct": false, "because": "Kein Kommunikationsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden unterstützen die Abstimmung mit Stakeholdern?', 5, '[{"text": "Umfragen", "correct": true, "because": "Sammelt Feedback"}, {"text": "Workshops", "correct": true, "because": "Fördert Zusammenarbeit"}, {"text": "Maximale Speichergröße", "correct": false, "because": "Nicht relevant"}, {"text": "Animationseffekte", "correct": false, "because": "Kein Kommunikationsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Abstimmung mit Stakeholdern verbessert Anpassung. b) Feedback ist optional. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Feedback ist essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Abstimmung mit Stakeholdern?', 4, '[{"text": "Kommunikationskanäle", "correct": false, "because": "Ermöglichen Austausch"}, {"text": "Stakeholder-Liste", "correct": false, "because": "Identifiziert Beteiligte"}, {"text": "Grafisches Design", "correct": true, "because": "Kein Kommunikationsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Abstimmung mit Stakeholdern nur für den Projektstart nötig?', 2, '[{"text": "Nein", "correct": true, "because": "Läuft durch das ganze Projekt"}, {"text": "Ja", "correct": false, "because": "Kontinuierlich erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte gehören zur Abstimmung mit Stakeholdern?', 4, '[{"text": "Bedarfsanalyse", "correct": true, "because": "Erfasst Anforderungen"}, {"text": "Feedback-Einholung", "correct": true, "because": "Passt Projekt an"}, {"text": "Visuelles Design", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Stakeholder-Abstimmung Zeitverschwendung ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Fördert Erfolg und Akzeptanz"}, {"text": "Ja", "correct": false, "because": "Wichtig für Anpassung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Abstimmung mit Stakeholdern?', 3, '[{"text": "Klare Kommunikation", "correct": true, "because": "Vermeidet Missverständnisse"}, {"text": "Schnelle Datenübertragung", "correct": false, "because": "Sekundär"}, {"text": "Schriftgröße", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Feedback hilft bei der Anpassung. b) Abstimmung ist nur für externe Stakeholder.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch interne Stakeholder"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Werkzeuge unterstützen die Abstimmung mit Stakeholdern?', 5, '[{"text": "E-Mail", "correct": true, "because": "Ermöglicht direkten Kontakt"}, {"text": "Projektmanagement-Tools", "correct": true, "because": "Koordiniert Feedback"}, {"text": "Maximale Speichergröße", "correct": false, "because": "Nicht relevant"}, {"text": "Animationseffekte", "correct": false, "because": "Kein Kommunikationsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Stakeholder-Abstimmung unwichtig?', 3, '[{"text": "Kommunikationsplan", "correct": false, "because": "Strukturiert Austausch"}, {"text": "Feedback", "correct": false, "because": "Fördert Verbesserung"}, {"text": "Schriftgröße", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Abstimmung mit Stakeholdern nur für den Projektabschluss?', 3, '[{"text": "Nein", "correct": true, "because": "Läuft kontinuierlich"}, {"text": "Ja", "correct": false, "because": "Durchgehend nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Feedback von Stakeholdern die Qualität verbessert?', 2, '[{"text": "Ja", "correct": true, "because": "Passt Projekt an Bedürfnisse an"}, {"text": "Nein", "correct": false, "because": "Teil der Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element wähle ich für die Abstimmung mit Stakeholdern?', 4, '[{"text": "Feedback-Meeting", "correct": true, "because": "Fördert direkten Austausch"}, {"text": "Zufällige Daten", "correct": false, "because": "Irrelevant"}, {"text": "Grafisches Design", "correct": false, "because": "Kein Kommunikationsfokus"}]');
